"""Independent check of poe report.html against the JSONL transcripts.

Does not import poe_report. Usage: python3 -I check.py <task dir>
"""
import html
import json
import re
import sys
from pathlib import Path

task = Path(sys.argv[1])
report = (task / "report.html").read_text(encoding="utf-8")
failures = []


def fail(message):
    failures.append(message)
    print("FAIL:", message)


# ---------------------------------------------------------------- JSONL side

def read_transcript(path):
    tool_uses = []          # (id, name, input) in file order
    results = {}            # tool_use_id -> (is_error, text)
    usage_by_id = {}
    usage_without_id = []
    raw_tool_use_count = 0
    bad_lines = 0
    for line in path.read_text(encoding="utf-8").splitlines():
        raw_tool_use_count += line.count('"type":"tool_use"')
        if not line.strip():
            continue
        try:
            record = json.loads(line)
        except ValueError:
            bad_lines += 1
            continue
        if not isinstance(record, dict):
            continue
        message = record.get("message")
        if not isinstance(message, dict):
            continue
        content = message.get("content")
        if record.get("type") == "assistant":
            usage = message.get("usage")
            if isinstance(usage, dict):
                if message.get("id"):
                    usage_by_id[message["id"]] = usage
                else:
                    usage_without_id.append(usage)
            if isinstance(content, list):
                for block in content:
                    if isinstance(block, dict) and block.get("type") == "tool_use":
                        tool_uses.append((block.get("id"), block.get("name"), block.get("input")))
        if record.get("type") == "user" and isinstance(content, list):
            for block in content:
                if isinstance(block, dict) and block.get("type") == "tool_result":
                    value = block.get("content")
                    if isinstance(value, list):
                        parts = []
                        for item in value:
                            if isinstance(item, dict) and item.get("type") == "text":
                                parts.append(item.get("text", ""))
                            elif isinstance(item, dict):
                                parts.append(f"[{item.get('type')} block]")
                        value = "\n".join(parts)
                    elif value is None:
                        value = ""
                    results[block.get("tool_use_id")] = (block.get("is_error") is True, str(value))
    totals = [0, 0, 0, 0]
    keys = ["input_tokens", "output_tokens", "cache_read_input_tokens", "cache_creation_input_tokens"]
    for usage in list(usage_by_id.values()) + usage_without_id:
        for i, key in enumerate(keys):
            value = usage.get(key)
            if isinstance(value, int):
                totals[i] += value
    return {
        "tool_uses": tool_uses,
        "results": results,
        "totals": totals,
        "raw_tool_use_count": raw_tool_use_count,
        "bad_lines": bad_lines,
        "usage_records_with_id": len(usage_by_id),
        "usage_records_without_id": len(usage_without_id),
    }


sessions = {}  # session id -> {name: data}
for session_dir in sorted((task / "logs").iterdir()):
    if not session_dir.is_dir():
        continue
    files = {}
    main_file = session_dir / f"{session_dir.name}.jsonl"
    if main_file.exists():
        files[session_dir.name] = read_transcript(main_file)
    for worker_file in sorted((session_dir / "subagents").glob("agent-*.jsonl")):
        files[worker_file.stem] = read_transcript(worker_file)
    sessions[session_dir.name] = files

# ---------------------------------------------------------------- HTML side

section_starts = [(m.start(), m.group(1)) for m in
                  re.finditer(r'<section class="transcript" id="transcript-([^"]+)">', report)]
step_pattern = re.compile(
    r'<div class="(step [^"]*)" id="([^"]*)"><div class="step-head">(.*?)</div>(.*?)</div>'
    r'(?=<div class="step |</section>)', re.S)
html_steps = {}  # transcript name -> list of steps
steps_by_anchor = {}
for match in step_pattern.finditer(report):
    owner = None
    for start, name in section_starts:
        if start < match.start():
            owner = name
    head = match.group(3)
    body = match.group(4)
    tool_name = re.search(r'<span class="mono">([^<]*)</span>', head)
    result_link = re.search(r'<a href="#([^"]+)">result #\d+</a>', head)
    preview = re.search(r'<span class="mono preview">(.*?)</span>', body, re.S)
    pres = re.findall(r'<pre>(.*?)</pre>', body, re.S)
    if preview:
        texts = [html.unescape(preview.group(1)), html.unescape(pres[0])]
    else:
        texts = [html.unescape(pres[0])] if pres else [None]
    step = {
        "classes": match.group(1),
        "anchor": match.group(2),
        "kind": re.search(r"kind-(\S+)", match.group(1)).group(1),
        "tool_name": html.unescape(tool_name.group(1)) if tool_name else None,
        "result_anchor": result_link.group(1) if result_link else None,
        "texts": texts,
    }
    html_steps.setdefault(owner, []).append(step)
    steps_by_anchor[step["anchor"]] = step


def text_matches(step, expected):
    texts = step["texts"]
    if len(texts) == 1:
        return texts[0] == expected
    return expected in (texts[0] + texts[1], texts[0] + "\n" + texts[1])


errors_section = re.search(r'<section id="errors">(.*?)</section>', report, re.S).group(1)
error_hrefs = re.findall(r'<li><a href="#([^"]+)">', errors_section)
errors_heading = re.search(r"<h2>Errors \((\d+)\)</h2>", errors_section).group(1)

# ---------------------------------------------------------------- compare

section_names = [name for _, name in section_starts]
grand = [0, 0, 0, 0]
total_tool_uses = 0
total_is_error = 0
total_results = 0
for session_id, files in sessions.items():
    session_totals = [0, 0, 0, 0]
    for name, data in files.items():
        if name not in section_names:
            fail(f"no section for {name}")
            continue
        calls = [s for s in html_steps.get(name, []) if s["kind"] == "tool_call"]
        uses = data["tool_uses"]
        total_tool_uses += len(uses)
        total_results += len(data["results"])
        print(f"{name}: tool_use blocks {len(uses)} (raw string count {data['raw_tool_use_count']}), "
              f"tool-call rows {len(calls)}, results {len(data['results'])}, "
              f"is_error {sum(1 for e, _ in data['results'].values() if e)}, bad lines {data['bad_lines']}, "
              f"usage msgs {data['usage_records_with_id']} ids + {data['usage_records_without_id']} no id, "
              f"tokens {data['totals']}")
        if len(calls) != len(uses):
            fail(f"{name}: {len(calls)} tool-call rows vs {len(uses)} tool_use blocks")
        result_anchor_by_id = {}
        for index, ((use_id, use_name, use_input), call) in enumerate(zip(uses, calls)):
            expected_input = json.dumps(use_input, indent=2, ensure_ascii=False)
            if call["tool_name"] != use_name or not text_matches(call, expected_input):
                fail(f"{name}: tool call #{index + 1} ({use_name}) differs from row {call['anchor']} ({call['tool_name']})")
            if use_id not in data["results"]:
                fail(f"{name}: tool_use {use_id} ({use_name}) has no tool_result in the JSONL")
                continue
            if call["result_anchor"] is None:
                fail(f"{name}: row {call['anchor']} has no result link")
                continue
            result_step = steps_by_anchor.get(call["result_anchor"])
            if result_step is None or result_step["kind"] != "tool_result":
                fail(f"{name}: result link {call['result_anchor']} does not resolve to a tool_result step")
                continue
            if not text_matches(result_step, data["results"][use_id][1]):
                fail(f"{name}: result text of {use_id} differs from {result_step['anchor']}")
            result_anchor_by_id[use_id] = call["result_anchor"]
        # order: anchors of tool-call rows must increase
        indexes = [int(c["anchor"].rsplit("-", 1)[1]) for c in calls]
        if indexes != sorted(indexes):
            fail(f"{name}: tool-call rows not in order")
        for use_id, (is_error, _) in data["results"].items():
            if not is_error:
                continue
            total_is_error += 1
            anchor = result_anchor_by_id.get(use_id)
            if anchor is None:
                fail(f"{name}: is_error result {use_id} has no matching call row")
            elif anchor not in error_hrefs:
                fail(f"{name}: is_error result {use_id} ({anchor}) not in Errors section")
        # per-transcript token line in HTML
        section_html = report[report.index(f'id="transcript-{name}"'):]
        section_html = section_html[:section_html.index("</section>")]
        expected_line = ("input {:,} · output {:,} · cache read {:,} · cache creation {:,}"
                         .format(*data["totals"]))
        if name.startswith("agent-"):
            if f"tokens: {expected_line}" not in section_html:
                fail(f"{name}: worker token line does not match {expected_line}")
        else:
            if f"orchestrator only: " not in section_html or \
                    f"tokens: {expected_line}" not in section_html.split("orchestrator only: ", 1)[1]:
                fail(f"{name}: orchestrator-only token line does not match {expected_line}")
        for i in range(4):
            session_totals[i] += data["totals"][i]
    session_line = "input {:,} · output {:,} · cache read {:,} · cache creation {:,}".format(*session_totals)
    session_html = report[report.index(f'id="transcript-{session_id}"'):]
    session_html = session_html[:session_html.index("orchestrator only: ")]
    if f"tokens: {session_line}" not in session_html:
        fail(f"session {session_id}: session token line does not match {session_line}")
    print(f"session {session_id}: tokens {session_totals}")
    for i in range(4):
        grand[i] += session_totals[i]

grand_line = "input {:,} · output {:,} · cache read {:,} · cache creation {:,}".format(*grand)
overview = re.search(r'<section id="overview">(.*?)</section>', report, re.S).group(1)
print("grand total tokens:", grand, "sum", sum(grand))
if grand_line not in overview:
    fail(f"overview token breakdown does not match {grand_line}")
if f'<div class="label">Tokens</div><div class="value">{sum(grand):,}</div>' not in overview:
    fail(f"overview Tokens card does not match {sum(grand):,}")

all_calls = sum(1 for steps in html_steps.values() for s in steps if s["kind"] == "tool_call")
print(f"sections in HTML: {len(section_names)}; transcripts on disk: {sum(len(f) for f in sessions.values())}")
print(f"tool_use blocks {total_tool_uses}, tool-call rows {all_calls}, tool_results {total_results}")
print(f"is_error results {total_is_error}, Errors section items {len(error_hrefs)} (heading {errors_heading})")
extra = set(section_names) - {n for f in sessions.values() for n in f}
if extra:
    fail(f"sections without a transcript: {extra}")
print("RESULT:", "PASS" if not failures else f"{len(failures)} failure(s)")

